''protected'',(SELECT protected_projection-''captured_at'' FROM (WITH targets(label,character_id) AS (VALUES (''pg_tamako'',''f335b077-34a1-41c3-94aa-58ec674b649b''::uuid),(''pg_riuji'',''6bceee99-974f-426b-8d92-38b43b4a4267''::uuid)), resources AS (select t.label,c.rank,c.vita,c.vita_max,c.chakra,c.chakra_max,c.exp,c.xp_lifetime,c.money,c.pool_concesso,c.unspent_points,md5(jsonb_build_array(c.taijutsu,c.ninjutsu,c.genjutsu,c.forza,c.velocita,c.mente,c.resistenza,c.fuuinjutsu,c.kekkei_genkai,c.lealta,c.via,c.fama,c.slot_extra)::text) stats_md5,(select count(*) from public.character_inventory x where x.character_id=c.id) inventory_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.item_id,x.quantity,x.created_at) order by x.id),''[]''::jsonb)::text) from public.character_inventory x where x.character_id=c.id) inventory_md5,(select count(*) from public.lesson_progress x where x.user_id=c.user_id) lesson_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.lesson_id,x.completed_at) order by x.id),''[]''::jsonb)::text) from public.lesson_progress x where x.user_id=c.user_id) lesson_md5,(select count(*) from public.character_jutsu x where x.user_id=c.user_id) jutsu_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.jutsu_id,x.source,x.learned_at) order by x.id),''[]''::jsonb)::text) from public.character_jutsu x where x.user_id=c.user_id) jutsu_md5,(select count(*) from public.character_abilities x where x.character_id=c.id) ability_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.technique_id,x.state,x.sessions_done,x.started_at,x.activated_at) order by x.id),''[]''::jsonb)::text) from public.character_abilities x where x.character_id=c.id) ability_md5,(select count(*) from public.character_perks x where x.character_id=c.id) perk_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.tipo,x.dettaglio,x.costo,x.grado_tecnica,x.created_at) order by x.id),''[]''::jsonb)::text) from public.character_perks x where x.character_id=c.id) perk_md5,(select count(*) from public.esame_prove x where x.candidate_user=c.user_id and x.stato=''aperta'') legacy_exam_open,(select count(*) from exam_regia_private.bindings x where x.owner_user=c.user_id and x.state<>''closed'') legacy_binding_open,md5(jsonb_build_array(c.clan,c.element,c.element2,c.cercoterio,c.sigillo)::text) identity_build_md5 from targets t join public.characters c on c.id=t.character_id order by t.label) select jsonb_build_object(''schema_version'',''c1266-protected-projection/1'',''captured_at'',clock_timestamp(),
''pg_count'',count(*),''fields_per_pg'',(select count(*) from jsonb_object_keys((select to_jsonb(x)-''label'' from resources x limit 1))),''protected_field_count'',count(*)*(select count(*) from jsonb_object_keys((select to_jsonb(x)-''label'' from resources x limit 1))),''projection_sha256'',public.combat_v2_sha256(jsonb_agg(to_jsonb(r) order by label))) as protected_projection from resources r) p)
) AS baseline' INTO actual;
 IF (((actual-'captured_at') #- '{root,updated_at}')=(expected #- '{root,updated_at}')) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'NPC_EDITORIAL_ONLY_DECLARED_DIFF' USING ERRCODE='40001';END IF;
 EXECUTE 'WITH scope AS(SELECT ''44078c5f-7001-4129-9506-e2f34e68c8ac''::uuid AS session_id)
SELECT jsonb_build_object(
 ''fati'',(SELECT jsonb_agg(jsonb_build_object(''id'',m.id,''body_sha256'',encode(extensions.digest(convert_to(m.body,''UTF8''),''sha256''),''hex''),''row_sha256'',public.combat_v2_sha256(to_jsonb(m))) ORDER BY m.id)
   FROM public.messages m WHERE m.id IN(''34c34697-768a-493a-b180-1045fcc4ea22''::uuid,''9b36f847-8f4f-49c5-9c4b-82278456ecad''::uuid,''e4b9e55c-7330-4406-bdce-a4fc374d30aa''::uuid,''7350d790-f581-431b-90a0-c7b9db29b05d''::uuid,''33c6ab57-6ae9-4eaa-be49-9cc57f402200''::uuid)),
 ''works'',(SELECT jsonb_agg(jsonb_build_object(''id'',w.id,''sha256'',public.combat_v2_sha256(to_jsonb(w))) ORDER BY w.id) FROM mission_generic_owner.work_items w,scope s WHERE w.master_session_id=s.session_id),
 ''roles'',(SELECT jsonb_agg(jsonb_build_object(''message_id'',r.message_id,''sha256'',public.combat_v2_sha256(to_jsonb(r))) ORDER BY r.message_id) FROM mission_generic_owner.role_submissions r,scope s WHERE r.master_session_id=s.session_id),
 ''batches'',(SELECT jsonb_agg(jsonb_build_object(''id'',b.id,''sha256'',public.combat_v2_sha256(to_jsonb(b)-''retired_at'')) ORDER BY b.id) FROM mission_generic_owner.unified_batches b,scope s WHERE b.master_session_id=s.session_id),
 ''source_windows'',(SELECT jsonb_agg(jsonb_build_object(''id'',sw.id,''sha256'',public.combat_v2_sha256(to_jsonb(sw))) ORDER BY sw.id) FROM mission_generic_owner.unified_source_windows sw,scope s WHERE sw.master_session_id=s.session_id),
 ''cursor'',(SELECT public.combat_v2_sha256(to_jsonb(c)) FROM mission_generic_owner.role_window_cursors c,scope s WHERE c.master_session_id=s.session_id),
 ''quota'',(SELECT jsonb_agg(jsonb_build_object(''id'',q.id,''sha256'',public.combat_v2_sha256(to_jsonb(q))) ORDER BY q.id) FROM staff_ai_quota_private.calls q,scope s WHERE q.scope_id=s.session_id),
 ''dispatch_receipts'',(SELECT jsonb_agg(jsonb_build_object(''id'',d.id,''sha256'',public.combat_v2_sha256(to_jsonb(d))) ORDER BY d.id) FROM mission_narrative_internal.dispatch_receipts d,scope s WHERE d.master_session_id=s.session_id),
 ''work_contracts'',(SELECT jsonb_agg(jsonb_build_object(''work_id'',c.work_id,''sha256'',public.combat_v2_sha256(to_jsonb(c))) ORDER BY c.work_id) FROM mission_public_owner.work_contracts_v1 c,scope s WHERE c.master_session_id=s.session_id),
 ''dispatch_audit'',(SELECT jsonb_agg(jsonb_build_object(''id'',a.id,''sha256'',public.combat_v2_sha256(to_jsonb(a))) ORDER BY a.id) FROM mission_narrative_internal.dispatch_audit a JOIN mission_narrative_internal.dispatch_receipts d ON d.id=a.receipt_id,scope s WHERE d.master_session_id=s.session_id),
 ''run_audit'',(SELECT jsonb_agg(jsonb_build_object(''id'',a.id,''sha256'',public.combat_v2_sha256(to_jsonb(a))) ORDER BY a.id) FROM public.mission_run_audit a,scope s WHERE a.master_session_id=s.session_id),
 ''binding'',(SELECT public.combat_v2_sha256(to_jsonb(b)-''retired_at'') FROM mission_generic_owner.run_bindings b,scope s WHERE b.master_session_id=s.session_id),
 ''session'',(SELECT public.combat_v2_sha256(to_jsonb(m)) FROM public.master_v2_sessions m,scope s WHERE m.id=s.session_id),
 ''run_state'',(SELECT public.combat_v2_sha256(to_jsonb(r)) FROM public.mission_run_state r,scope s WHERE r.master_session_id=s.session_id),
 ''active_work_count'',(SELECT count(*) FROM mission_generic_owner.work_items w,scope s WHERE w.master_session_id=s.session_id AND w.state IN(''ready'',''claimed'',''authorized'',''provider_started'',''uncertain''))
) AS extra' INTO after_extra;
 IF (after_extra=before_extra) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'NPC_EDITORIAL_SCENE_KEEP' USING ERRCODE='40001';END IF;
 IF (NOT EXISTS(SELECT 1 FROM mission_generic_owner.work_items WHERE state IN('claimed','authorized','provider_started')) AND NOT EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_attempts WHERE status IN('reserved','authorized','provider_started')) AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.work_items WHERE master_session_id='44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid AND state IN('ready','claimed','authorized','provider_started','uncertain'))) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'NPC_EDITORIAL_ACTIVE_WORK_AFTER' USING ERRCODE='40001';END IF;
END $request_10x_install$;
NOTIFY pgrst,'reload schema';
COMMIT;
